def main():
    N = int(input())
    A = list(map(int, input().split()))
    A.sort()
    B = list(map(int, input().split()))
    B.sort()
    sum_a = sum(A)
    sum_b = sum(B)
    k = sum_b - sum_a

    now = 0
    while now < N and A[now] == B[now]:
        now += 1

    while k > 0 and now < N:
        while now < N and  A[now] == B[now]:
            now += 1

        if now < N:
            l = A[now] - B[now]
            if k >= l:
                k -= l
                A[now] += 2*l
                B[now] += l
            else:
                k = 0
                now = -1
                break

            if A[now] == B[now]:
                now += 1

    if now == N:
        print("Yes")
    else:
        print("No")

if __name__ == "__main__":
    main()

