def main():
    n = int(readline())
    a = list(map(int, readline().split()))
    b = list(map(int, readline().split()))

    cnt = sum(b) - sum(a)

    i = 0

    while i < n - 1:
        diff = a[i] - b[i]
        if diff < 0:
            if diff % 2 == 1:
                b[i] += 1
                a[i] += abs(diff) + 1
            else:
                a[i] += abs(diff)
                b[i + 1] += abs(diff) // 2
        elif diff > 0:
            b[i] += diff
            a[i + 1] += 2 * diff
        i += 1

    if a[n - 1] <= b[n - 1]:
        print("Yes")
    else:
        print("No")


