def Z(): return int(input())
def ZZ(): return [int(_) for _ in input().split()]

def main():
    N = Z()
    A = ZZ()
    B = ZZ()
    if A == B:
        print('Yes')
        return
    sa, sb = sum(A), sum(B)
    if sa >= sb:
        print('No')
        return

    target_sum = 2 * sb - sa
    cc = 0
    for a, b in zip(A, B): cc += max(a, b)
    if cc < target_sum: print('Yes')
    elif cc == target_sum:
        print('Yes' if all([a <= b and a%2 == b%2 for a, b in zip(A, B)]) else 'No')
    else: print('No')

    return

