def solve():
    n = II()
    a = LI()
    b = LI()
    suma = sum(a)
    sumb = sum(b)
    diff = sumb - suma
    tmp = 0
    for i in range(n):
        tmp += max((b[i] - a[i] + 1) // 2, 0)
    if diff >= tmp:
        print("Yes")
    else:
        print("No")
    return


