from math import ceil


def main():
    length = int(input())
    a = list(map(int, input().split()))
    b = list(map(int, input().split()))
    required_operation = sum(b) - sum(a)
    count_operation = 0
    for i in range(length):
        if a[i] < b[i]:
            count_operation += ceil((b[i] - a[i]) / 2)
        else:
            count_operation += a[i] - b[i]
    print("Yes" if required_operation == count_operation else "No")


if __name__ == '__main__':
    main()

